          "v": "from itertools import product\n\nres = []\nfor p in product(['0', '1'], repeat=20):\n    lenta = [' '] + list(p) + [' ']\n    lenta_start = list(lenta)\n    state = 0\n    cur_index = 21\n    count_change = 0 # Считаем число замен\n    while True:\n        if state == 0:\n            if lenta[cur_index] == ' ':\n                lenta[cur_index] = ' '\n                cur_index -= 1\n                state = 1\n        if state == 1:\n            if lenta[cur_index] == ' ':\n                lenta[cur_index] = ' '\n                break\n            elif lenta[cur_index] == '1':\n                lenta[cur_index] = '0'\n                count_change += 1\n                break\n            elif lenta[cur_index] == '0':\n                lenta[cur_index] = '1'\n                cur_index -= 1\n                state = 1\n                count_change += 1\n    if lenta.count('0') == 10:\n        # Добавляем на первое место число замен, чтобы по нему сортировать\n        res.append([count_change, lenta_start, lenta])\n\nres.sort(reverse=True)\nfor n, lenta_start, lenta_end in res[:100]:\n    lenta_start = ''.join(lenta_start)\n    lenta_end = ''.join(lenta_end)\n    print(n, lenta_start, lenta_end)"
